import { test, expect } from 'bun:test';
import { createLimiter } from '../src/limiter.js';
const make = (limit, windowMs) => { const clock = { t: 0 }; return { clock, lim: createLimiter({ limit, windowMs, now: () => clock.t }) }; };
test('allows up to the limit then denies', () => {
  const { lim } = make(3, 1000);
  expect([lim.allow('a'), lim.allow('a'), lim.allow('a'), lim.allow('a')]).toEqual([true, true, true, false]);
});
test('allows again once the window has passed', () => {
  const { clock, lim } = make(2, 1000);
  lim.allow('a'); lim.allow('a');
  expect(lim.allow('a')).toBe(false);
  clock.t = 2000;
  expect(lim.allow('a')).toBe(true);
});
test('keys are independent', () => {
  const { lim } = make(1, 1000);
  expect(lim.allow('a')).toBe(true);
  expect(lim.allow('b')).toBe(true);
  expect(lim.allow('a')).toBe(false);
});

