import { test, expect } from 'bun:test';
import { createLimiter } from '../src/limiter.js';
const make = (limit, windowMs) => { const clock = { t: 0 }; return { clock, lim: createLimiter({ limit, windowMs, now: () => clock.t }) }; };
test('no burst of twice the limit across a window edge', () => {
  const { clock, lim } = make(3, 1000);
  const at = (t) => { clock.t = t; return lim.allow('a'); };
  expect([at(900), at(950), at(990)]).toEqual([true, true, true]);
  expect([at(1010), at(1020), at(1500)]).toEqual([false, false, false]);
  expect(at(1901)).toBe(true);
});
test('denied calls do not use up quota', () => {
  const { clock, lim } = make(2, 1000);
  const at = (t) => { clock.t = t; return lim.allow('a'); };
  expect([at(0), at(100), at(500), at(900)]).toEqual([true, true, false, false]);
  expect(at(1001)).toBe(true);
  expect(at(1101)).toBe(true);
  expect(at(1102)).toBe(false);
});
